function validate([words]) {
  if (!Array.isArray(words) || words.length < 1 || words.length > 1000) return 'words holds 1 to 1000 words.';
  for (const word of words) {
    if (typeof word !== 'string' || word.length < 1 || word.length > 30) return 'Each word has 1 to 30 letters.';
    if (!/^[a-z]+$/.test(word)) return 'Words use lowercase English letters only.';
  }
  return null;
}

