function longestWord(words) {
  const root = { children: new Array(26).fill(null), word: null };
  for (const word of words) {
    let node = root;
    for (const ch of word) {
      const index = ch.charCodeAt(0) - 97;
      if (node.children[index] === null) {
        node.children[index] = { children: new Array(26).fill(null), word: null };
      }
      node = node.children[index];
    }
    node.word = word;
  }

  let best = '';
  function visit(node) {
    for (const child of node.children) {
      if (child === null || child.word === null) {
        continue;
      }
      if (child.word.length > best.length) {
        best = child.word;
      }
      visit(child);
    }
  }
  visit(root);
  return best;
}

