function longestWord(words) {
  const dictionary = new Set(words);
  let answer = '';
  for (const w of words) {
    let buildable = true;
    for (let len = 1; len < w.length; len++) {
      if (!dictionary.has(w.slice(0, len))) {
        buildable = false;
        break;
      }
    }
    if (buildable && (w.length > answer.length || (w.length === answer.length && w < answer))) answer = w;
  }
  return answer;
}

