function generate(rand, size) {
  const large = size === 'large';
  const letters = large ? 'abcdefghijklmnopqrstuvwxyz' : 'abc'.slice(0, 2 + Math.floor(rand() * 2));
  const letter = () => letters[Math.floor(rand() * letters.length)];
  const count = large ? 1000 : 1 + Math.floor(rand() * 8);
  const maxLen = large ? 30 : 4;
  const words = [];
  while (words.length < count) {
    const roll = rand();
    if (words.length === 0 || roll < 0.2) {
      words.push(letter());
    } else if (roll < 0.8) {
      // Extend an earlier word, so chains of prefixes are common.
      const base = words[Math.floor(rand() * words.length)];
      words.push(base.length < maxLen ? base + letter() : base);
    } else {
      const len = 1 + Math.floor(rand() * maxLen);
      words.push(Array.from({ length: len }, letter).join(''));
    }
  }
  for (let i = words.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [words[i], words[j]] = [words[j], words[i]];
  }
  return [words];
}
